"""Pick the can from the table and place it upright on the place zone.

Phase machine driven by obs["hand_pos"] (grasp point) and obs["finger_width"]. A setpoint moves at
limited speed toward each phase's goal; ik() turns the setpoint into arm joint targets with the gripper
kept pointing down.
"""

import numpy as np

from sim.control import GRIPPER_CLOSED, GRIPPER_OPEN, HOME_QPOS, ik

APPROACH_Z = 0.22  # grasp point height while travelling above the table
GRASP_Z = 0.05  # grasp point at can mid-height (can center z = 0.05)
LOWER_Z = 0.055  # grasp point height when placing the can down
SPEED = 0.25  # m/s, setpoint speed limit
POS_TOL = 0.006  # m, phase reached when hand is this close to the goal
SETTLE_STEPS = 25  # 0.5 s hold for gripper actions


class Controller:
    def reset(self, task):
        self.task = task
        self.can0 = np.array(task["can_start"], dtype=float)
        self.place = np.array(task["place_target"], dtype=float)
        self.done = False
        self.phase = "approach"
        self.sp = None  # setpoint (grasp point xyz)
        self.q = np.array(HOME_QPOS, dtype=float)
        self.grip = GRIPPER_OPEN
        self.count = 0
        self.last_width = None
        self.dt = 1.0 / task.get("control_hz", 50)

    def _goal(self, phase, obs):
        cx, cy = self.can0
        px, py = self.place
        if phase == "approach":
            return np.array([cx, cy, APPROACH_Z])
        if phase == "descend":
            return np.array([cx, cy, GRASP_Z])
        if phase == "lift":
            return np.array([cx, cy, APPROACH_Z])
        if phase == "transfer":
            return np.array([px, py, APPROACH_Z])
        if phase == "lower":
            return np.array([px, py, LOWER_Z])
        if phase == "retreat":
            return np.array([px, py, APPROACH_Z])
        return None

    def act(self, obs):
        hand = np.asarray(obs["hand_pos"], dtype=float)
        width = float(obs["finger_width"])
        if self.sp is None:
            self.sp = hand.copy()

        if self.phase == "approach":
            self.grip = GRIPPER_OPEN
        elif self.phase == "close":
            self.grip = GRIPPER_CLOSED
            self.count += 1
            if self.last_width is not None and abs(width - self.last_width) < 2e-5 and self.count > 10:
                self.count_stable = getattr(self, "count_stable", 0) + 1
            else:
                self.count_stable = 0
            self.last_width = width
            if self.count >= SETTLE_STEPS and getattr(self, "count_stable", 0) >= 10:
                self._next("lift")
        elif self.phase == "release":
            self.grip = GRIPPER_OPEN
            self.count += 1
            if self.count >= SETTLE_STEPS:
                self._next("retreat")
        elif self.phase == "done_hold":
            self.grip = GRIPPER_OPEN
        elif self.phase in ("lift", "transfer", "lower", "retreat", "descend"):
            pass

        goal = self._goal(self.phase, obs)
        if goal is not None:
            delta = goal - self.sp
            dist = np.linalg.norm(delta)
            step = SPEED * self.dt
            if dist > step:
                self.sp = self.sp + delta / dist * step
            else:
                self.sp = goal.copy()
            if np.linalg.norm(hand - goal) < POS_TOL and np.linalg.norm(self.sp - goal) < 1e-6:
                self._advance(obs)

        # Keep the gripper pointing down; seed from the last solution for continuity.
        self.q = ik(self.sp, q_init=self.q, down_weight=0.5)
        return list(self.q) + [self.grip]

    def _next(self, phase):
        self.phase = phase
        self.count = 0
        self.last_width = None
        self.count_stable = 0

    def _advance(self, obs):
        order = {
            "approach": "descend",
            "descend": "close",
            "lift": "transfer",
            "transfer": "lower",
            "lower": "release",
            "retreat": "done_hold",
        }
        if self.phase == "descend":
            self._next("close")
        elif self.phase in order and order[self.phase] != "close":
            self._next(order[self.phase])
        if self.phase == "done_hold":
            self.done = True

